// Get user message and content from database
const firstInput = $input.first();
const webhookData = firstInput && firstInput.json ? firstInput.json : {};
const userMessage = webhookData.message || webhookData.body?.message || '';
const userName = webhookData.userName || webhookData.body?.userName || 'مستخدم';
const userId = webhookData.userId || webhookData.body?.userId || '';

// Get content from second input (Supabase)
const allInputs = $input.all();
const contentData = allInputs.length > 1 && allInputs[1].json ? allInputs[1].json : [];
const contentList = Array.isArray(contentData) ? contentData : [];

// Build context about available content
let contentContext = '';
if (contentList && contentList.length > 0) {
  contentContext = '\n\nالمحتوى المتاح في منصة فطن:\n';
  contentList.slice(0, 10).forEach(item => {
    const type = item.content_type === 'book' ? 'كتاب' : 
                 item.content_type === 'video' ? 'فيديو' : 
                 item.content_type === 'article' ? 'مقال' : 'محتوى';
    contentContext += `- ${type}: ${item.title}${item.description ? ' - ' + item.description.substring(0, 100) : ''}\n`;
  });
}

// System prompt for Gemini
const systemPrompt = `أنت مساعد ذكي في منصة "فطن" - منصة تعليمية متخصصة في الأمن الفكري.

مهمتك:
1. الإجابة على الأسئلة المتعلقة بالأمن الفكري فقط
2. إذا سأل المستخدم عن موضوع غير متعلق بالأمن الفكري، قل له بأدب أنك متخصص في الأمن الفكري فقط
3. استخدم اللغة العربية الفصحى المبسطة
4. كن مهذباً ومحترماً
5. إذا كان هناك محتوى متعلق بالسؤال في قاعدة البيانات، اقترحه على المستخدم

القواعد المهمة:
- لا تجيب على أسئلة لا علاقة لها بالأمن الفكري
- لا تعطي معلومات طبية أو قانونية أو مالية
- ركز فقط على: المفاهيم الفكرية، الحماية من التطرف، التفكير الناقد، الوعي الفكري
- أجب دائماً بالعربية

${contentContext}`;

const fullPrompt = `${systemPrompt}\n\nالمستخدم (${userName}): ${userMessage}\n\nالمساعد:`;

return [{
  json: {
    prompt: fullPrompt,
    userMessage: userMessage,
    userName: userName,
    userId: userId,
    contentAvailable: contentList.length > 0,
    contentList: contentList.slice(0, 5)
  }
}];

