// Extract response from Gemini API
const geminiResponse = $input.first().json;
const previousData = $input.first().json;

let aiResponse = '';

try {
  // Extract text from Gemini response
  if (geminiResponse.candidates && geminiResponse.candidates.length > 0) {
    const candidate = geminiResponse.candidates[0];
    if (candidate.content && candidate.content.parts && candidate.content.parts.length > 0) {
      aiResponse = candidate.content.parts[0].text;
    }
  }

  // If no response, use fallback
  if (!aiResponse) {
    aiResponse = 'عذراً، لم أتمكن من معالجة سؤالك. يرجى المحاولة مرة أخرى.';
  }

  // Check if we should suggest content
  const userMessage = previousData.userMessage?.toLowerCase() || '';
  const contentList = previousData.contentList || [];

  // Add content suggestions if relevant
  if (contentList.length > 0 && aiResponse.length > 50) {
    const relevantContent = contentList.filter(item => {
      const title = item.title?.toLowerCase() || '';
      const desc = item.description?.toLowerCase() || '';
      return title.includes('أمن') || title.includes('فكر') || 
             desc.includes('أمن') || desc.includes('فكر');
    });

    if (relevantContent.length > 0) {
      aiResponse += '\n\n📚 محتوى مقترح قد يفيدك:\n';
      relevantContent.slice(0, 3).forEach((item, index) => {
        const type = item.content_type === 'book' ? '📖' : 
                     item.content_type === 'video' ? '🎥' : '📄';
        aiResponse += `${index + 1}. ${type} ${item.title}\n`;
      });
    }
  }

} catch (error) {
  aiResponse = 'عذراً، حدث خطأ في معالجة الرد. يرجى المحاولة مرة أخرى.';
}

return [{
  json: {
    response: aiResponse,
    timestamp: new Date().toISOString(),
    userId: previousData.userId,
    userName: previousData.userName
  }
}];
